function cancelMaterializeTimeoutMs(jobParams) {
    var n = (jobParams || {}).cancelMaterializeTimeoutMs;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    return (typeof n === 'number' && !isNaN(n) && n >= 0)
