        // Live bug doctrine (fa 2026-09-27): DRY means NO side effects —
        // a dry tick must not cancel live queued runs.
        console.log('  🧪 [dry] stale-cancel skipped (' + ciWorkflow + ' @ ' +
                    branch + ', head ' + String(currentSha).slice(0, 7) + ')');
        return empty;
