        var result = { cancelled: [], deferred: [], cleaned: [] };
        // gh-848 guard window (jobParams-tunable, header doc).
        var matTimeoutMs = cancelMaterializeTimeoutMs(RUN_JOB_PARAMS);
        var matPollMs = cancelMaterializePollMs(RUN_JOB_PARAMS);
