                                String(r.head_sha).slice(0, 7) +
                                ' — jobs not materialized yet (retried next tick)');
                    return;
                }
                cli_execute_command({
                    command: 'gh api -X POST repos/' +
                        repoInfo.owner + '/' + repoInfo.repo +
                        '/actions/runs/' + r.id + '/cancel || true'
