//
// Live fa #1457 (2026-10-10): a dispatched CI run cancelled while queued
// (gh-748 twin-guard family) left its `in_progress` check runs on the head
// forever; branch protection takes the LATEST check-run per (context, head),
// so the ghosts held mergeStateStatus=BLOCKED ~2h even though the head ALSO
// carried green terminal entries from the earlier run 38057801418. The tick
// read its rollup green and the green-cover guard (skipIfGreenCi) concluded
// "the blocker is not this CI" — no re-dispatch ever fired. The gh-821
// run-level zombie sweep missed it: the newest EXISTING dispatched run was
// the old green one. This probe closes that gap at the CHECK-RUN level.
//
// Two reads, both in the established fail-open probe family:
//   - the head's check runs (bridge tool — the same REST list
//     computePrStatus falls back to);
//   - the head's run rollup (headWorkflowRunsSafe) as the resolver source:
//     a check-run's backing run is looked up BY ID (parsed from its
//     details_url); ABSENT from the head's list is the 404-equivalent
//     (deleted runs simply do not appear).
// Probe failure on EITHER side ⇒ null (caller keeps the legacy behavior —
// the green-cover skip stands; a degraded read must not turn into a
// re-dispatch churn, and the next tick retries with a healthy API).

function headCheckRunsSafe(repoInfo, headSha) {
    try {
        var res = github_get_commit_check_runs({
            workspace: repoInfo.owner,
            repository: repoInfo.repo,
            commitSha: headSha
        });
        var parsed = mcpParse(res);
        return (parsed && parsed.check_runs) || [];
    } catch (e) {
        console.warn('  ⚠️  head check-run probe failed: ' + (e.message || e));
        return null;
    }
}

function headCheckRunZombies(repoInfo, headSha) {
    // → null (probe degraded — caller keeps legacy behavior) | the
    // classify() result {zombies, live, settled, unresolvable}.
    var checkRuns = headCheckRunsSafe(repoInfo, headSha);
    if (checkRuns === null) return null;
    if (!checkRuns.length) return { zombies: [], live: 0, settled: 0, unresolvable: 0 };
    var runs = headWorkflowRunsSafe(repoInfo, headSha);
    if (runs === null) return null;
    var byId = {};
    runs.forEach(function (r) {
        if (r && r.id !== undefined && r.id !== null) byId[String(r.id)] = r;
    });
    return checkRunZombiesModule.classify(checkRuns, function (runId) {
        var hit = byId[String(runId)];
        return hit === undefined ? null : hit;
    }, Date.now(), {
        staleNoRunnerMinutes: (RUN_JOB_PARAMS || {}).checkRunZombieStaleMinutes,
        runConcludedGraceMinutes: (RUN_JOB_PARAMS || {}).checkRunZombieGraceMinutes
    });
}

// Placeholder probe (gh-852) — the check-run-level twin of
// headCheckRunZombies, at the PLACEHOLDER grace (default 3 min), not the
// 30-min zombie staleness: GitHub mints pending placeholder check-runs
// ~20s after a dispatch that queued without materializing a job; while
// they are young they are indistinguishable from a live dispatch's fresh
// bridge stamp (both link-less), so only the short grace safely separates
// them. Same transport contract: null = the check-run probe failed — the
// caller keeps the legacy behavior (fail safe toward live).
function headPlaceholders(repoInfo, headSha) {
    var checkRuns = headCheckRunsSafe(repoInfo, headSha);
    if (checkRuns === null) return null;
    return checkRunZombiesModule.placeholders(checkRuns, Date.now(), {
        placeholderMinutes: (RUN_JOB_PARAMS || {}).checkRunPlaceholderMinutes
    });
}

// gh-852 AC2 pool-free probe: a fresh-sha reset cures the placeholder-pinned
// gate ONLY when the next dispatch materializes its first job immediately —
// a queued dispatch mints FRESH placeholders on the new head ~20s later and
// the pathology re-arms. "No ACTIVE run repo-wide" is the conservative
// proxy for the ticket's "no in_progress macos/ubuntu-arm runs" (self-hosted
// runner labels ride job objects, not the run list). Also subsumes the
// gh-798 leg guard: an in-flight ai-teammate leg IS an active run, so a
// pool-free read proves no leg owns the head either. Returns
// true (pool free) | false (busy) | null (probe failed — callers fail
// CLOSED: one deferred reset costs a tick, a reset under a busy pool
// re-mints the placeholders it exists to clear).
function repoPoolFree(repoInfo) {
    try {
        var runs = mcpParse(github_list_workflow_runs({
            workspace: repoInfo.owner, repository: repoInfo.repo,
            perPage: 50
        })) || {};
        var list = runs.workflow_runs || runs.workflowRuns || [];
        var busy = list.some(function (r) {
            return r && validationLivenessModule.ACTIVE_RUN_STATES
                .indexOf(String(r.status || '').toLowerCase()) !== -1;
        });
        return !busy;
    } catch (ePool) {
        console.warn('  ⚠️  pool-free probe failed: ' + (ePool.message || ePool));
        return null;
    }
}


function hasActiveHeadRun(runs) {
    // hasActiveDispatchedRun semantics, widened to every run on the head:
    // any queued/in-progress/waiting/pending run means the state is about
    // to move on its own (a fresh kicker stamps the contexts, a validation
    // dispatch re-runs them) — rerunning cancelled runs under it would
    // only stack. Takes the pre-fetched head rollup (the action fetches
    // once and shares it with the target mapping — #695 review); a null
    // (failed probe) reads as no active run — fail OPEN. The ACTIVE
    // vocabulary comes from js/common/validationLiveness.js (gh-821 round-2
    // review: one constant, not parallel inline lists that drift).
    return (runs || []).some(function (r) {
        return validationLivenessModule.ACTIVE_RUN_STATES.indexOf(r.status) !== -1;
    });
}

