            var c = top.conclusion ? String(top.conclusion).toUpperCase() : null;
            if (c === 'SUCCESS') return { state: 'green', pendingSince: null };
            if (c === 'FAILURE' || c === 'TIMED_OUT' || c === 'CANCELLED') return { state: 'red', pendingSince: null };
