        var among = q.mutexAmong;
        var holdsMutex = function (it) {
            if (it.labels.indexOf(q.mutex) === -1) return false;
            if (!among) return true;
            return among.some(function (l) { return it.labels.indexOf(l) !== -1; });
        };
